      {
        "src": "/assets/live/products/nylon-bag/01-custom-nylon-bags-set.webp",
        "alt": "A set of three custom nylon bags in green, blue, and red, crafted from durable, water-repellent polyamide fibers. These lightweight, abrasion-resistant bags are ideal for travel, school, retail, or promotional giveaways, with customizable logos and designs. Offered by PuffSticker.com with fast delivery and quality assurance.",
        "name": "custom-nylon-bags-set.webp"
      }
